// ============================================================
//  Menopause Self-Assessment — Score Calculator
//  Based on the Q003 Make.com blueprint.
//
//  18 yes/no questions. Yes = 1 point, No = 0. Max = 18.
//
//  Scoring tiers — mirroring Q003 blueprint switch exactly:
//    score = 0        → Result 1 (No symptoms)
//    score 1–14       → Result 2 (Mild–Moderate symptoms)
//    score 15–18      → Result 3 (Significant symptoms)
// ============================================================

const data = $input.first().json.body || $input.first().json;

const fields = [
  'q1_water_retention',
  'q2_facial_hair',
  'q3_breast_tenderness',
  'q4_pain',
  'q5_vaginal_dryness',
  'q6_fatigue',
  'q7_concentration',
  'q8_urinary_incontinence',
  'q9_irritability',
  'q10_anxiety',
  'q11_mood_swings',
  'q12_depression',
  'q13_acne',
  'q14_low_libido',
  'q15_hot_flashes',
  'q16_sleep_disturbance',
  'q17_heart_disease_risk',
  'q18_osteoporosis_risk'
];

let totalScore = 0;
const scores = {};
const warnings = [];

for (const field of fields) {
  const raw = data[field];
  const isYes = raw && String(raw).trim().toLowerCase() === 'yes';
  const score = isYes ? 1 : 0;
  scores[field] = { raw, score };
  totalScore += score;
  if (!raw) warnings.push(field + ' is missing');
}

// Three-tier result — matching Q003 blueprint switch exactly
let resultNum, resultLabel, resultContent;
if (totalScore === 0) {
  resultNum = 1;
  resultLabel = 'No Symptoms Reported';
  resultContent = 'You have not reported any menopause symptoms at this time. This is a positive result. Establishing a hormone baseline now and monitoring for changes as you move through your 40s and 50s is recommended.';
} else if (totalScore >= 1 && totalScore <= 14) {
  resultNum = 2;
  resultLabel = 'Mild to Moderate Symptoms';
  resultContent = 'You are experiencing a number of symptoms that may be linked to menopause. Declining oestrogen, progesterone, and testosterone levels are the most likely cause. A comprehensive hormone panel will clarify your hormonal status and open the door to effective evidence-based treatment options including bioidentical hormone replacement therapy (BHRT).';
} else {
  resultNum = 3;
  resultLabel = 'Significant Symptoms';
  resultContent = 'You are reporting a high number of menopause symptoms that are significantly impacting your quality of life. The wide range of symptoms you are experiencing are well-documented consequences of declining oestrogen and progesterone. We strongly recommend a comprehensive hormone assessment and a specialist consultation as soon as possible to discuss BHRT and other treatment options.';
}

return [{ json: {
  patientName:    data.first_name   || '',
  patientEmail:   data.email        || '',
  mailingList:    data.mailing_list || '',
  totalScore,
  resultNum,
  resultLabel,
  resultContent,
  _debug_scores:   scores,
  _debug_warnings: warnings
}}];

const d = $input.first().json;
// Escape only the dynamic name used in the HTML greeting.
function escapePatientName(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}
const greeting = d.patientName ? ('Dear ' + escapePatientName(d.patientName)) : 'Hi there';
const year = new Date().getFullYear();

const introMap = {
  1: `Menopause is a natural biological transition that occurs when the ovaries cease producing oestrogen and progesterone, typically between the ages of 45 and 55. While it marks the end of reproductive years, its hormonal effects can significantly impact health and wellbeing — affecting bone density, cardiovascular health, mood, cognition, sleep, and sexual function.<br/><br/>Based on your responses, you are not currently reporting symptoms associated with menopause. This is encouraging. However, we recommend establishing a hormone baseline now — even without symptoms — so you and your clinician have a clear reference point for any future changes. A female hormone panel is a straightforward and informative step that can be done from home.<br/><br/>Protecting your long-term bone and cardiovascular health through regular weight-bearing exercise, adequate calcium and vitamin D intake, a heart-healthy diet, and avoiding smoking and excess alcohol are the most impactful things you can do now to stay well through and after the menopause transition.`,
  2: `Menopause is a significant hormonal transition in which oestrogen, progesterone, and testosterone all decline — sometimes gradually, sometimes rapidly — producing a wide and variable range of symptoms that can affect virtually every aspect of your physical and emotional health.<br/><br/>Based on your responses, you are experiencing a number of symptoms that are consistent with menopause or the late perimenopause transition. These symptoms — which may include hot flashes, sleep disruption, mood changes, vaginal dryness, joint pain, fatigue, and cognitive changes — are not 'just ageing' and you do not have to simply accept them.<br/><br/>A comprehensive hormone panel will identify exactly which hormones have declined and by how much, giving you and your clinician the information needed to design an effective treatment plan. Bioidentical hormone replacement therapy (BHRT) uses hormones structurally identical to those your body produces naturally, and has a strong evidence base for relieving menopause symptoms while protecting bone density and cardiovascular health.<br/><br/>We encourage you to take the next step and speak with one of our specialists — who understand menopause deeply and can guide you through your options clearly and compassionately.`,
  3: `Menopause is the permanent cessation of menstruation following the decline of ovarian oestrogen and progesterone production. When this hormonal withdrawal is significant — as your symptom score suggests — it can affect nearly every organ system in the body, from the brain and heart to bones, skin, and the genitourinary system.<br/><br/>Scoring 15 or more symptoms indicates that menopause is having a substantial and wide-ranging impact on your health and quality of life. The symptoms you are experiencing are real, measurable, and — critically — highly treatable. Women who receive appropriate hormonal support during and after menopause report dramatically better quality of life, and the evidence for protecting bone density and cardiovascular health through BHRT is well established.<br/><br/>You should not have to suffer through menopause. With the right assessment and a personalised treatment plan, most women experience significant relief within 2–3 months of starting BHRT. The risks of appropriately prescribed, monitored bioidentical HRT are, for most women, considerably outweighed by the benefits — particularly when started within 10 years of menopause onset.<br/><br/>Please reach out to our specialists as a matter of priority. A comprehensive hormone panel is the essential first step, and from there we can build a treatment plan tailored specifically to you.`
};

const introText = introMap[d.resultNum] || introMap[2];

const labTests = [
  {
    img: 'https://cdn.shopify.com/s/files/1/0150/2081/8486/products/ZRTBloodSpotTestKit-9_1024x1024_2x_3025b07b-9b81-4d8f-85a4-2c9aff366530_1024x1024@2x.jpg?v=1571716034',
    title: 'Female Hormone Panel — At Home Test Kit',
    desc: 'Measures FSH, LH, oestradiol, and progesterone from a simple blood spot collected at home. Ideal for confirming menopause status and monitoring BHRT.',
    price: '$179.00',
    url: 'https://store.hrt.org/products/female-hormone-panel-at-home-test-kit'
  },
  {
    img: 'https://cdn.shopify.com/s/files/1/0150/2081/8486/products/ZRTLabBloodUrineMultiTestKit_1024x1024@2x.jpg?v=1571716011',
    title: 'Comprehensive Female Hormone Profile (Blood Spot)',
    desc: 'Full hormonal picture: oestradiol, progesterone, testosterone, DHEA-S, cortisol, and thyroid. Clinician-reviewed results. Essential for moderate-to-significant menopause symptoms.',
    price: '$269.00',
    url: 'https://store.hrt.org/products/comprehensive-female-hormone-profile-blood-spot'
  },
  {
    img: 'https://cdn.shopify.com/s/files/1/0150/2081/8486/products/Thyroid_Health_Essentials_1024x1024_upclose_1024x1024@2x.png?v=1579640010',
    title: 'Elite Female Hormone Panel (Blood Spot/Urine)',
    desc: 'Our most comprehensive menopause profile. Includes oestrogen metabolites, adrenal hormones, bone and cardiovascular markers — the complete picture for significant menopause.',
    price: '$299.00',
    url: 'https://store.hrt.org/products/elite-female-hormone-panel'
  }
];

const products = [
  {
    img: 'https://cdn.shopify.com/s/files/1/0150/2081/8486/products/2056x2056_product_photos_Micronized_DHEA_transparent_1024x1024@2x.png?v=1571716034',
    title: 'DHEA (25mg) — Natural Hormone Support',
    desc: 'DHEA is a precursor to oestrogen and testosterone, both of which decline significantly at menopause. Micronised DHEA supports energy, libido, mood, and overall hormonal balance in menopausal women.',
