  return `<th bgcolor="#FFFFFF" width="171" valign="top" style="vertical-align:top;font-weight:normal;padding:15px;-webkit-box-shadow:0 0 5px 0 rgba(0,0,0,.25);border-radius:5px;" class="force-col-th"><a href="${b.url}" target="_blank" class="a_block"><table width="100%" border="0" cellspacing="0" cellpadding="0"><tr><td align="center" class="blog_box"><table width="100%" border="0" cellspacing="0" cellpadding="0"><tr><td align="center" style="padding-bottom:10px;"><div style="height:106px;overflow:hidden"><img alt="${b.title}" border="0" class="w159" height="106" src="${b.img}" style="width:159px;max-width:159px;height:auto;" width="159"></div></td></tr><tr><td style="padding-bottom:5px;"><div align="center" style="color:#4e525e;font-size:12px;font-family:'Open Sans',sans-serif;font-weight:300;text-transform:uppercase;">${b.title}</div></td></tr><tr><td><div align="center" style="color:#4e525e;font-size:12px;font-family:'Open Sans',sans-serif;font-weight:300;">HRT.org Blog</div></td></tr></table></td></tr></table></a></th>`;
